1346	            @Nullable
1347	            private Collection<DBSObjectContainer> obtainDefaultContext(
1348	                @NotNull DBRProgressMonitor monitor,
1349	                @NotNull SQLCompletionRequest request
1350	            ) {
1351	                if (dbcExecutionContext == null) {
1352	                    return Collections.emptyList();
1353	                }
1354	                DBCExecutionContextDefaults<?, ?> defaults = dbcExecutionContext.getContextDefaults();
1355	                if (defaults != null) {
1356	                    DBSSchema defaultSchema = defaults.getDefaultSchema();
1357	                    DBSCatalog defaultCatalog = defaults.getDefaultCatalog();
1358	                    if (defaultCatalog == null && defaultSchema == null
1359	                        && dbcExecutionContext.getDataSource() instanceof DBSObjectContainer container
1360	                    ) {
1361	                        return List.of(container);
1362	                    } else if (defaultCatalog != null && request.getContext().isSearchGlobally()) {
1363	                        Set<DBSObjectContainer> result = new HashSet<>();
1364	                        findAllSchemaContainers(monitor, defaultCatalog, result);
1365	                        return result;
1366	                    } else if (defaultCatalog != null && defaultSchema == null) {
1367	                        return List.of(defaultCatalog);
1368	                    } else if (defaultSchema != null) {
1369	                        return List.of(defaultSchema);
1370	                    }
1371	                } else if (dbcExecutionContext.getDataSource() instanceof DBSObjectContainer container) {
1372	                    return List.of(container);
1373	                }
1374	                return Collections.emptyList();
1375	            }
