505	                                    accumulator.addLast(SQLQueryCompletionItem.forRealTable(
506	                                        score, childName, contextObjext, o,
507	                                        knownSources.getReferencedTables().contains(o),
508	                                        associations.hasRelatedAssociationsWithTable(o)
509	                                    ));
