519	            private SQLQueryCompletionItem makeDbObjectCompletionItem(
520	                int score,
521	                @NotNull SQLQueryWordEntry childName,
522	                @Nullable SQLQueryCompletionItem.ContextObjectInfo contextObjext,
523	                @NotNull DBSObject child
524	            ) {
