725	                List<SQLQueryWordEntry> parts = new ArrayList<>(nameNodes.length);
726	                int i = 0;
727	                for (; i < nameNodes.length; i++) {
728	                    STMTreeNode term = nameNodes[i];
729	                    if ((term instanceof STMTreeTermNode t && t.symbol.getType() != SQLStandardLexer.Period)||term instanceof  STMTreeTermErrorNode) {
730	                        if (term.getRealInterval().b + 1 < position) {
731	                            parts.add(new SQLQueryWordEntry(term.getRealInterval().a, term.getTextContent()));
732	                        } else {
733	                            break;
734	                        }
735	                    }
736	                }
737	                STMTreeNode currentNode = i >= nameNodes.length ? null : nameNodes[i];
738	                String currentPart = currentNode == null
739	                    ? null
740	                    : currentNode.getTextContent().substring(0, position - currentNode.getRealInterval().a);
741	                parts.add(currentPart == null ? null : new SQLQueryWordEntry(currentNode.getRealInterval().a, currentPart));
742	                return parts;
743	            }
