 519	            private void collectContainerChildren(
 520	                @NotNull DBRProgressMonitor monitor,
 521	                @NotNull Collection<DBSObjectContainer> containers,
 522	                @Nullable Predicate<DBSObject> filter,
 523	                @Nullable SQLQueryWordEntry filterOrNull,
 524	                @NotNull LinkedList<SQLQueryCompletionItem> accumulator,
 525	                @NotNull CompletionItemProducer<DBSObject> itemProducer
 526	            ) throws DBException {
 527	                for (DBSObjectContainer container : containers) {
 528	                    Collection<? extends DBSObject> children = container.getChildren(monitor);
 529	                    for (DBSObject child : children) {
 530	                        if (DBUtils.isHiddenObject(child) || (filter != null && !filter.test(child))) {
 531	                            continue;
 532	                        }
 533	                        SQLQueryWordEntry childName = makeFilterInfo(filterOrNull, child.getName());
 534	                        int score = childName.matches(filterOrNull, this.searchInsideWords);
 535	                        if (score > 0) {
 536	                            accumulator.addLast(itemProducer.produce(score, childName, child));
 537	                        }
 538	                    }
 539	                }
 540	            }
