1460	            private void collectProcedures(
1461	                @NotNull DBRProgressMonitor monitor,
1462	                @NotNull SQLCompletionRequest request,
1463	                @NotNull Collection<DBSObjectContainer> containers,
1464	                @Nullable SQLQueryCompletionItem.ContextObjectInfo contextObjext,
1465	                @Nullable SQLQueryWordEntry filterOrNull,
1466	                @NotNull LinkedList<SQLQueryCompletionItem> accumulator
1467	            ) throws DBException {
1468	                if (!request.getContext().isSearchProcedures()) {
1469	                    return;
1470	                }
1471	                boolean supportsStoredCode = request.getContext().getDataSource().getInfo().supportsStoredCode();
1472	                for (DBSObjectContainer container : containers) {
1473	                    if (supportsStoredCode && container instanceof DBSProcedureContainer pc) {
1474	                        this.collectProceduresFromContainer(monitor, pc, contextObjext, filterOrNull, accumulator);
1475	                    }
1476	                }
1477	                if (!containers.isEmpty()) {
1478	                    this.collectBuiltinFunctions(request, contextObjext, filterOrNull, accumulator);
1479	                }
1480	            }
