1482	            private void collectProceduresFromContainer(
1483	                @NotNull DBRProgressMonitor monitor,
1484	                @NotNull DBSProcedureContainer container,
1485	                @Nullable SQLQueryCompletionItem.ContextObjectInfo contextObjext,
1486	                @Nullable SQLQueryWordEntry filterOrNull,
1487	                @NotNull LinkedList<SQLQueryCompletionItem> accumulator
1488	            ) throws DBException {
1489	                Collection<? extends DBSProcedure> procedures = container.getProcedures(monitor);
1490	                if (procedures != null) {
1491	                    for (DBSProcedure procedure : procedures) {
1492	                        SQLQueryWordEntry childName = makeFilterInfo(filterOrNull, procedure.getName());
1493	                        int score = childName.matches(filterOrNull, this.searchInsideWords);
1494	                        if (score > 0) {
1495	                            accumulator.addLast(SQLQueryCompletionItem.forProcedureObject(score, childName, contextObjext, procedure));
1496	                        }
1497	                    }
1498	                }
1499	            }
