1501	            private void collectBuiltinFunctions(
1502	                @NotNull SQLCompletionRequest request,
1503	                @Nullable SQLQueryCompletionItem.ContextObjectInfo contextObjext,
1504	                @Nullable SQLQueryWordEntry filterOrNull,
1505	                @NotNull LinkedList<SQLQueryCompletionItem> accumulator
1506	            ) {
1507	                if (filterOrNull == null || contextObjext != null) {
1508	                    return;
1509	                }
1510	                for (String fname : request.getContext().getDataSource().getSQLDialect().getFunctions()) {
1511	                    SQLQueryWordEntry childName = makeFilterInfo(filterOrNull, fname);
1512	                    int score = childName.matches(filterOrNull, this.searchInsideWords);
1513	                    if (score > 0) {
1514	                        accumulator.addLast(SQLQueryCompletionItem.forBuiltinFunction(score, childName, fname));
1515	                    }
1516	                }
1517	            }
