1519	            private void collectTables(

1299	                @Nullable SQLQueryWordEntry filterOrNull,
1300	                @NotNull List<SQLQueryCompletionSet> results
1301	            ) {
1302	                LinkedList<SQLQueryCompletionItem> completions = new LinkedList<>();
1303	
1304	                AssociationsResolutionContext associations = this.getAssociationsContext(monitor, this.deepestContext, filterOrNull);
1305	                for (SourceResolutionResult rr : knownSources.getResolutionResults().values()) {
1306	                    if (rr.aliasOrNull != null && rr.isCteSubquery) {
1307	                        SQLQueryWordEntry aliasName = makeFilterInfo(filterOrNull, rr.aliasOrNull.getName());
1308	                        int score = aliasName.matches(filterOrNull, this.searchInsideWords);
1309	                        if (score > 0) {
1310	                            completions.add(SQLQueryCompletionItem.forRowsSourceAlias(
1311	                                score, aliasName, rr.aliasOrNull, rr,
1312	                                associations.hasRelatedAssociationsWithTable(rr.source)
1313	                            ));
1314	                        }
1315	                    }
1316	                }
1317	
1318	                if (dbcExecutionContext != null) {
1319	                    try {
1320	                        Collection<DBSObjectContainer> containers = this.obtainDefaultContext(monitor, request);
1321	                        this.collectTables(monitor, knownSources, containers, null, filterOrNull, completions);
1322	                        // usually we don't want procedures in FROM
1323	                        //this.collectProcedures(monitor, request, containers, null, filterOrNull, completions);
1324	                        this.collectPackages(monitor, request, this.exposedContexts, null, filterOrNull, completions);
1325	                    } catch (DBException e) {
1326	                        log.error(e);
1327	                    }
1328	                }
1329	                
1330	                this.makeFilteredCompletionSet(filterOrNull, completions, results);
1331	                this.prepareContextSchemasAndCatalogs(monitor, this.exposedContexts, null, filterOrNull, results);
1332	            }
