1334	            private void prepareObjectCompletions(
1335	                @NotNull DBRProgressMonitor monitor,
1336	                @NotNull SQLCompletionRequest request,
1337	                @NotNull SQLQuerySourcesInfoCollection knownSources,
1338	                @NotNull Collection<DBSObjectContainer> contexts,
1339	                @Nullable SQLQueryCompletionItem.ContextObjectInfo contextObjext,
1340	                @NotNull Set<DBSObjectType> objectTypes,
1341	                @Nullable SQLQueryWordEntry filterOrNull,
1342	                @NotNull List<SQLQueryCompletionSet> results
1343	            ) {
1344	                LinkedList<SQLQueryCompletionItem> completions = new LinkedList<>();
1345	                Set<DBSObject> objs = new HashSet<>();
1346	                try {
1347	                    this.collectImmediateChildren(
1348	                        monitor,
1349	                        knownSources,
1350	                        contexts,
1351	                        o -> objectTypes.stream().anyMatch(t -> t.getTypeClass().isAssignableFrom(o.getClass())) && objs.add(o),
1352	                        contextObjext,
1353	                        filterOrNull,
1354	                        completions
1355	                    );
1356	                    if (request.getContext().isSearchProcedures()
1357	                        && objectTypes.stream().anyMatch(t -> DBSProcedure.class.isAssignableFrom(t.getTypeClass()))
1358	                    ) {
1359	                        this.collectProcedures(monitor, request, contexts, contextObjext, filterOrNull, completions);
1360	                    }
1361	                } catch (DBException e) {
1362	                    log.error(e);
1363	                }
1364	                this.makeFilteredCompletionSet(filterOrNull, completions, results);
1365	            }
