1367	            @Nullable
1368	            private Collection<DBSObjectContainer> obtainDefaultContext(
1369	                @NotNull DBRProgressMonitor monitor,
1370	                @NotNull SQLCompletionRequest request
1371	            ) {
1372	                if (dbcExecutionContext == null) {
1373	                    return Collections.emptyList();
1374	                }
1375	                DBCExecutionContextDefaults<?, ?> defaults = dbcExecutionContext.getContextDefaults();
1376	                if (defaults != null) {
1377	                    DBSSchema defaultSchema = defaults.getDefaultSchema();
1378	                    DBSCatalog defaultCatalog = defaults.getDefaultCatalog();
1379	                    if (defaultCatalog == null && defaultSchema == null
1380	                        && dbcExecutionContext.getDataSource() instanceof DBSObjectContainer container
1381	                    ) {
1382	                        return List.of(container);
1383	                    } else if (defaultCatalog != null && request.getContext().isSearchGlobally()) {
1384	                        Set<DBSObjectContainer> result = new HashSet<>();
1385	                        findAllSchemaContainers(monitor, defaultCatalog, result);
1386	                        return result;
1387	                    } else if (defaultCatalog != null && defaultSchema == null) {
1388	                        return List.of(defaultCatalog);
1389	                    } else if (defaultSchema != null) {
1390	                        return List.of(defaultSchema);
1391	                    }
1392	                } else if (dbcExecutionContext.getDataSource() instanceof DBSObjectContainer container) {
1393	                    return List.of(container);
1394	                }
1395	                return Collections.emptyList();
1396	            }
