1398	            private void findAllSchemaContainers(
1399	                @NotNull DBRProgressMonitor monitor,
1400	                @NotNull DBSObjectContainer container,
1401	                @NotNull Set<DBSObjectContainer> result
1402	            ) {
1403	                try {
1404	                    if (result.add(container)) {
1405	                        Collection<? extends DBSObject> dbObjs = container.getChildren(monitor);
1406	                        for (DBSObject obj : dbObjs) {
1407	                            if (obj instanceof DBSObjectContainer child && (obj instanceof DBSCatalog || obj instanceof DBSSchema)) {
1408	                                findAllSchemaContainers(monitor, child, result);
1409	                            }
1410	                        }
1411	                    }
1412	                } catch (DBException ex) {
1413	                    log.error(ex);
1414	                }
1415	            }
